export type VarianceScope={tenant:string;property:string;session:string;actor:string};
export const varianceOutcomes=['investigating','explained','adjustment_required'] as const;
export type VarianceOutcome=typeof varianceOutcomes[number];
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v);
function object(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid variance review.');return v as Record<string,unknown>}
function integer(v:unknown,signed=false){if(typeof v!=='string'||!(signed?/^-?(0|[1-9][0-9]{0,11})$/:/^(0|[1-9][0-9]{0,11})$/).test(v)||v==='-0')throw Error('Invalid variance amount or revision.');return BigInt(v)}
function text(v:unknown,max=500){if(typeof v!=='string'||!v.trim()||v.length>max)throw Error('Incomplete variance review.');return v}
function scoped(v:unknown,s:VarianceScope){const r=object(v);if(!Object.values(s).every(uuid)||r.schema_version!==1||r.tenant_id!==s.tenant||r.property_id!==s.property||r.actor_id!==s.actor||r.session_id!==s.session)throw Error('Variance review scope changed.');return r}
export function readVarianceHistory(value:unknown,scope:VarianceScope,before:string|null=null){
 const r=scoped(value,scope),closing=object(r.closing_review),revision=integer(r.current_revision),count=integer(r.history_count);
 if(r.currency!=='USD'||closing.tenant_id!==scope.tenant||closing.property_id!==scope.property||closing.session_id!==scope.session||!Array.isArray(r.history)||r.history.length>100||typeof r.can_review!=='boolean'||typeof r.history_complete!=='boolean')throw Error('Invalid variance history.');
 const expected=integer(closing.opening_minor)+integer(closing.receipts_minor)-integer(closing.refunds_minor)+integer(closing.cash_in_minor)-integer(closing.cash_out_minor),counted=integer(closing.counted_minor),variance=counted-expected;
 if(integer(closing.expected_minor,true)!==expected||integer(closing.variance_minor,true)!==variance||r.can_review!==(variance!==BigInt(0)))throw Error('Drawer amounts do not reconcile.');
 let previous=before===null?revision+BigInt(1):integer(before);const history=r.history.map(value=>{const row=object(value),n=integer(row.revision);if(n<1||n!==previous-BigInt(1)||n>revision||!uuid(row.request_id)||!uuid(row.actor_id)||!varianceOutcomes.includes(row.outcome as VarianceOutcome))throw Error('Invalid variance history sequence.');previous=n;return {revision:n.toString(),request_id:row.request_id,actor_id:row.actor_id,outcome:row.outcome as VarianceOutcome,reason:text(row.reason),created_at:text(row.created_at)};});
 const upper=before===null?revision:integer(before)-BigInt(1);if(count!==revision||upper<0||upper>revision||BigInt(history.length)!==(upper>BigInt(100)?BigInt(100):upper))throw Error('Variance history has missing revisions.');
 const next=r.next_before_revision;if((next===null)!==(upper<=BigInt(100)))throw Error("Variance history cursor is missing.");if(next!==null&&(typeof next!=='string'||history.length!==100||next!==history[99].revision))throw Error('Invalid variance history cursor.');
 if(count< BigInt(history.length)||r.history_complete!==(before===null&&count<=BigInt(100))||(r.history_complete&&BigInt(history.length)!==count))throw Error('Incomplete variance history.');
 return {revision:revision.toString(),history,count:count.toString(),next:next as string|null,canReview:r.can_review,expected:expected.toString(),counted:counted.toString(),variance:variance.toString(),closingReason:text(r.closing_reason),closedAt:text(r.closed_at)};
}export type VarianceRequest={scope:VarianceScope;request:string;revision:string;outcome:VarianceOutcome;reason:string};
export function prepareVarianceRequest(scope:VarianceScope,request:string,revision:string,outcome:string,reason:string):VarianceRequest{
 if(!Object.values(scope).every(uuid)||!uuid(request)||integer(revision)>BigInt('999999999998')||!varianceOutcomes.includes(outcome as VarianceOutcome)||reason!==reason.trim()||reason.length<4||reason.length>500||/[\x00-\x1f\x7f]/.test(reason))throw Error('Review the variance outcome and explanation.');
 return {scope:{...scope},request,revision,outcome:outcome as VarianceOutcome,reason};
}
export function varianceArgs(r:VarianceRequest){return {p_tenant:r.scope.tenant,p_property:r.scope.property,p_session:r.scope.session,p_request:r.request,p_expected_revision:r.revision,p_outcome:r.outcome,p_reason:r.reason,p_confirmed:true}}
export function readVarianceReceipt(value:unknown,request:VarianceRequest){const r=scoped(value,request.scope);if(r.request_id!==request.request||r.revision!==(integer(request.revision)+BigInt(1)).toString()||r.outcome!==request.outcome||r.reason!==request.reason||r.journal_posted!==false||r.cash_recovered!==false||typeof r.replayed!=='boolean')throw Error('Variance receipt does not match the saved review.');integer(r.variance_minor,true);text(r.created_at);return r;}
export function readVarianceStatus(value:unknown,request:VarianceRequest){const r=object(value),s=request.scope;if(r.schema_version!==1||r.tenant_id!==s.tenant||r.property_id!==s.property||r.actor_id!==s.actor||r.request_id!==request.request||typeof r.found!=='boolean')throw Error('Variance recovery scope changed.');if(!r.found){if(r.result!==null)throw Error('Invalid variance recovery result.');return null}return readVarianceReceipt(r.result,request)}
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function storageKey(s:VarianceScope){if(!Object.values(s).every(uuid))throw Error('Invalid variance workspace.');return 'irp.cashier.variance.v1:'+ [s.tenant,s.property,s.session,s.actor].join(':')}
export function loadVarianceRequest(store:Store,scope:VarianceScope){const raw=store.getItem(storageKey(scope));if(raw===null)return null;const r=object(JSON.parse(raw)),s=object(r.scope);if(s.tenant!==scope.tenant||s.property!==scope.property||s.session!==scope.session||s.actor!==scope.actor)throw Error('Saved variance scope changed.');return prepareVarianceRequest(scope,text(r.request),text(r.revision),text(r.outcome),text(r.reason))}
export function saveVarianceRequest(store:Store,r:VarianceRequest){const checked=prepareVarianceRequest(r.scope,r.request,r.revision,r.outcome,r.reason),prior=loadVarianceRequest(store,r.scope),encoded=JSON.stringify(checked);if(prior&&JSON.stringify(prior)!==encoded)throw Error('Resolve the pending variance review first.');const key=storageKey(r.scope);store.setItem(key,encoded);if(store.getItem(key)!==encoded)throw Error('Unable to preserve variance review.');}
export function clearVarianceRequest(store:Store,r:VarianceRequest){const prior=loadVarianceRequest(store,r.scope);if(prior&&prior.request!==r.request)throw Error('A different variance review is pending.');const key=storageKey(r.scope);store.removeItem(key);if(store.getItem(key)!==null)throw Error('Unable to clear variance review.');}